source.command:
gh api graphql -F owner='{owner}' -F name='{repo}' -F number="{{epic}}" -f query='
query($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    issue(number: $number) {
      number title
      subIssues(first: 100) {
        nodes {
          number title body state url
          labels(first: 30) { nodes { name } }
          blockedBy(first: 50) { nodes { number state labels(first: 30) { nodes { name } } } }
          subIssues(first: 50) {
            nodes {
              number state
              labels(first: 30) { nodes { name } }
              blockedBy(first: 20) { nodes { number state parent { number } } }
            }
          }
        }
      }
    }
  }
}' --jq '
"feature" as $require | [] as $skip | [] as $done
| def implemented: any(.labels.nodes[].name | ascii_downcase; . == "implemented");
  def open_work: .state != "CLOSED" and (implemented | not);
.data.repository.issue as $parent
| [ $parent.subIssues.nodes[]
    | (.labels.nodes | map(.name | ascii_downcase)) as $labels
    | select(any($labels[]; . == $require))
    | select(any($labels[]; IN($skip[])) | not) ] as $features
| ($features | map(.number)) as $listed
| ([ $features[].subIssues.nodes[] | { key: (.number | tostring), value: implemented } ] | from_entries) as $implemented
| [ $features[]
    | (.labels.nodes | map(.name | ascii_downcase)) as $labels
    | .number as $self
    | ([ .blockedBy.nodes[] | { id: (.number | tostring), done: (open_work | not) } ]
      + [ .subIssues.nodes[] | select(open_work) | .blockedBy.nodes[]
          | select(.state != "CLOSED" and $implemented[.number | tostring] != true)
          | .parent.number // empty
          | select(. != $self and IN($listed[]))
          | { id: tostring, done: false } ]) as $blockers
    | { id: (.number | tostring), number, title, body: (.body // ""), url, state,
        labels: [.labels.nodes[].name],
        parent: { number: $parent.number, title: $parent.title },
        dependsOn: (reduce $blockers[] as $b ([]; if any(.[]; .id == $b.id) then . else . + [$b] end)),
        done: (.state == "CLOSED" or any($labels[]; IN($done[]))) } ]'
